import os
from typing import Optional

from azure.identity import DefaultAzureCredential
from azure.keyvault.keys import KeyClient
from azure.keyvault.keys.crypto import CryptographyClient, EncryptionAlgorithm


class AzureKeyVaultKMS:
    def __init__(self, vault_url: Optional[str] = None, key_name: Optional[str] = None):
        self.vault_url = vault_url or os.environ.get("AZURE_KEY_VAULT_URL")
        self.key_name = key_name or os.environ.get("AZURE_KEY_VAULT_KEY_NAME")
        if not self.vault_url:
            raise ValueError("AZURE_KEY_VAULT_URL is required")
        if not self.key_name:
            raise ValueError("AZURE_KEY_VAULT_KEY_NAME is required")

        credential = DefaultAzureCredential()
        self._key_client = KeyClient(vault_url=self.vault_url, credential=credential)
        self._cryptography_client = None

    def _get_cryptography_client(self) -> CryptographyClient:
        if self._cryptography_client is None:
            key_bundle = self._key_client.get_key(self.key_name)
            self._cryptography_client = CryptographyClient(key_bundle.key, credential=DefaultAzureCredential())
        return self._cryptography_client

    def encrypt(self, plaintext: bytes) -> bytes:
        if not isinstance(plaintext, (bytes, bytearray)):
            raise TypeError("plaintext must be bytes")
        client = self._get_cryptography_client()
        result = client.encrypt(EncryptionAlgorithm.rsa_oaep, bytes(plaintext))
        return result.ciphertext

    def decrypt(self, ciphertext: bytes) -> bytes:
        if not isinstance(ciphertext, (bytes, bytearray)):
            raise TypeError("ciphertext must be bytes")
        client = self._get_cryptography_client()
        result = client.decrypt(EncryptionAlgorithm.rsa_oaep, bytes(ciphertext))
        return result.plaintext

    def sign(self, digest: bytes) -> bytes:
        if not isinstance(digest, (bytes, bytearray)):
            raise TypeError("digest must be bytes")
        client = self._get_cryptography_client()
        result = client.sign("RS256", bytes(digest))
        return result.signature

    def verify(self, digest: bytes, signature: bytes) -> bool:
        if not isinstance(digest, (bytes, bytearray)):
            raise TypeError("digest must be bytes")
        if not isinstance(signature, (bytes, bytearray)):
            raise TypeError("signature must be bytes")
        client = self._get_cryptography_client()
        result = client.verify("RS256", bytes(digest), bytes(signature))
        return bool(result.is_valid)
